@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --primary: #1868DB;
  --primary-hover: #1459BD;
  --accent: #FF613D;
  --accent-hover: #E35332;
  --text-dark: #292A2E;
  --text-light: #5A5C63;
  --bg-light: #F9FAFB;
  --bg-alt: #F3F5F9;
  --white: #FFFFFF;
  --border: #E5E7EB;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 24px;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Inter', sans-serif;
  color: var(--text-dark);
  line-height: 1.6;
  background-color: var(--white);
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: var(--primary); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--primary-hover); }
ul { list-style: none; }

/* Typography */
h1, h2, h3, h4 { color: var(--text-dark); font-weight: 700; line-height: 1.2; letter-spacing: -0.02em; }
h1 { font-size: 3.5rem; margin-bottom: 1.5rem; }
h2 { font-size: 2.5rem; margin-bottom: 1rem; }
h3 { font-size: 1.5rem; margin-bottom: 0.75rem; }
p { font-size: 1.125rem; color: var(--text-light); margin-bottom: 1.5rem; }
.text-center { text-align: center; }
.mb-1 { margin-bottom: 1rem; } .mb-2 { margin-bottom: 2rem; } .mb-3 { margin-bottom: 3rem; } .mb-4 { margin-bottom: 4rem; }

/* Layout */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 96px 0; }
.section-sm { padding: 48px 0; }
.bg-light { background-color: var(--bg-light); }
.bg-alt { background-color: var(--bg-alt); }

.grid { display: grid; gap: 32px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }
}

/* Flex Utilities */
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: 16px; }
.gap-3 { gap: 24px; }
.gap-4 { gap: 32px; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 12px 24px; font-weight: 600; font-size: 1rem;
  border-radius: var(--radius-sm); border: none; cursor: pointer;
  transition: all 0.2s; text-decoration: none;
}
.btn-primary { background: var(--primary); color: var(--white); }
.btn-primary:hover { background: var(--primary-hover); color: var(--white); transform: translateY(-1px); }
.btn-secondary { background: var(--accent); color: var(--white); }
.btn-secondary:hover { background: var(--accent-hover); color: var(--white); transform: translateY(-1px); }
.btn-outline { background: transparent; border: 2px solid var(--border); color: var(--text-dark); }
.btn-outline:hover { border-color: var(--text-dark); color: var(--text-dark); }
.btn-social { background: var(--white); border: 1px solid var(--border); color: var(--text-dark); width: 100%; padding: 12px; font-weight: 500; }
.btn-social:hover { background: var(--bg-light); border-color: #d1d5db; }
.btn-block { width: 100%; }

/* Badges */
.badge { display: inline-block; padding: 4px 12px; border-radius: 99px; font-size: 0.875rem; font-weight: 600; }
.badge-new { background: #E0E7FF; color: var(--primary); margin-bottom: 16px; }
.badge-popular { background: #FEF3C7; color: #D97706; font-size: 0.75rem; padding: 2px 8px; }

/* Navigation */
.navbar { padding: 16px 24px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--border); position: sticky; top: 0; background: rgba(255, 255, 255, 0.95); backdrop-filter: blur(8px); z-index: 100; }
.navbar-brand { font-size: 1.5rem; font-weight: 700; color: var(--primary); letter-spacing: -0.5px; }
.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a { color: var(--text-dark); font-weight: 500; }
.nav-links a:hover { color: var(--primary); }
.nav-actions { display: flex; gap: 16px; align-items: center; }
@media (max-width: 768px) { .nav-links { display: none; } }

/* Hero */
.hero { padding: 120px 0; text-align: center; max-width: 800px; margin: 0 auto; }
.hero-graphic { margin-top: 64px; border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-lg); background: #eee; aspect-ratio: 16/9; display: flex; align-items: center; justify-content: center; }

/* Cards & Grid Items */
.card { background: var(--white); border-radius: var(--radius-md); padding: 32px; border: 1px solid var(--border); box-shadow: var(--shadow-sm); transition: transform 0.2s, box-shadow 0.2s; }
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.card-icon { width: 48px; height: 48px; border-radius: 12px; background: var(--bg-light); display: flex; align-items: center; justify-content: center; margin-bottom: 24px; color: var(--primary); font-size: 24px; }
.logo-bar { display: flex; justify-content: center; gap: 48px; flex-wrap: wrap; opacity: 0.6; filter: grayscale(100%); margin-top: 32px; }

/* Pricing */
.pricing-toggle { display: inline-flex; align-items: center; background: var(--bg-light); border-radius: 99px; padding: 4px; margin: 32px auto; }
.toggle-btn { padding: 8px 24px; border-radius: 99px; border: none; background: transparent; cursor: pointer; font-weight: 500; color: var(--text-light); transition: all 0.2s; }
.toggle-btn.active { background: var(--white); color: var(--text-dark); box-shadow: var(--shadow-sm); }
.save-badge { color: var(--accent); font-size: 0.75rem; font-weight: 700; margin-left: 8px; }
.pricing-card { display: flex; flex-direction: column; position: relative; }
.pricing-card.popular { border-color: var(--primary); box-shadow: 0 0 0 2px var(--primary); }
.pricing-price { font-size: 2.5rem; font-weight: 700; color: var(--text-dark); margin: 16px 0; display: flex; align-items: baseline; gap: 4px; }
.pricing-price span { font-size: 1rem; color: var(--text-light); font-weight: 400; }
.pricing-features { margin-top: 32px; flex-grow: 1; }
.pricing-features li { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 16px; font-size: 0.95rem; }
.pricing-features li::before { content: "✓"; color: var(--primary); font-weight: bold; }

/* Comparison Table */
.comparison-table { width: 100%; border-collapse: collapse; margin-top: 64px; text-align: left; }
.comparison-table th { padding: 24px 16px; font-weight: 600; border-bottom: 2px solid var(--border); background: var(--white); position: sticky; top: 70px; z-index: 10; }
.comparison-table td { padding: 20px 16px; border-bottom: 1px solid var(--border); color: var(--text-dark); font-size: 0.95rem; }
.comparison-table td:first-child { font-weight: 500; color: var(--text-dark); }
.comparison-table tr:hover td { background: var(--bg-light); }

/* Range Slider */
.slider-container { max-width: 600px; margin: 32px auto; text-align: center; }
input[type=range] { width: 100%; margin: 16px 0; -webkit-appearance: none; background: var(--border); height: 8px; border-radius: 4px; outline: none; }
input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 24px; height: 24px; border-radius: 50%; background: var(--primary); cursor: pointer; border: 4px solid var(--white); box-shadow: var(--shadow-md); }

/* FAQ Accordion */
.faq-item { border-bottom: 1px solid var(--border); }
.faq-question { width: 100%; text-align: left; padding: 24px 0; background: transparent; border: none; font-size: 1.125rem; font-weight: 600; color: var(--text-dark); cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
.faq-question::after { content: '+'; font-size: 1.5rem; color: var(--text-light); transition: transform 0.2s; }
.faq-question[aria-expanded="true"]::after { transform: rotate(45deg); }
.faq-answer { display: none; padding-bottom: 24px; color: var(--text-light); line-height: 1.6; }
.faq-question[aria-expanded="true"] + .faq-answer { display: block; }

/* Auth Forms */
.auth-wrapper { min-height: 100vh; display: flex; }
.auth-main { flex: 1; display: flex; align-items: center; justify-content: center; padding: 24px; background: var(--white); }
.auth-sidebar { flex: 1; background: var(--bg-alt); padding: 48px; display: flex; align-items: center; justify-content: center; }
@media (max-width: 992px) { .auth-sidebar { display: none; } }
.auth-box { width: 100%; max-width: 400px; }
.form-group { margin-bottom: 20px; }
.form-label { display: block; font-size: 0.875rem; font-weight: 500; margin-bottom: 8px; color: var(--text-dark); }
.form-input { width: 100%; padding: 12px 16px; border: 1px solid var(--border); border-radius: var(--radius-sm); font-size: 1rem; transition: border-color 0.2s; outline: none; }
.form-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1); }
.divider { display: flex; align-items: center; text-align: center; margin: 24px 0; color: var(--text-light); font-size: 0.875rem; }
.divider::before, .divider::after { content: ''; flex: 1; border-bottom: 1px solid var(--border); }
.divider:not(:empty)::before { margin-right: .25em; }
.divider:not(:empty)::after { margin-left: .25em; }

/* Cookie Banner */
.cookie-banner { position: fixed; bottom: 24px; left: 24px; right: 24px; max-width: 600px; background: var(--white); padding: 24px; border-radius: var(--radius-md); box-shadow: var(--shadow-lg); z-index: 1000; border: 1px solid var(--border); display: flex; flex-direction: column; gap: 16px; }
.cookie-actions { display: flex; gap: 12px; }
.cookie-modal { display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 1001; align-items: center; justify-content: center; padding: 24px; }
.cookie-modal.active { display: flex; }
.cookie-modal-content { background: var(--white); padding: 32px; border-radius: var(--radius-md); width: 100%; max-width: 500px; }

/* Footer */
.footer { background: var(--white); padding: 80px 0 40px; border-top: 1px solid var(--border); }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 64px; }
@media (max-width: 992px) { .footer-grid { grid-template-columns: 1fr 1fr; } }
.footer h4 { font-size: 0.875rem; margin-bottom: 24px; color: var(--text-dark); text-transform: uppercase; letter-spacing: 0.05em; }
.footer ul li { margin-bottom: 12px; }
.footer a { color: var(--text-light); font-size: 0.95rem; }
.footer a:hover { color: var(--primary); }
.footer-bottom { border-top: 1px solid var(--border); padding-top: 24px; display: flex; justify-content: space-between; color: var(--text-light); font-size: 0.875rem; }

document.addEventListener('DOMContentLoaded', () => {

  // FAQ Accordion
  const faqQuestions = document.querySelectorAll('.faq-question');
  faqQuestions.forEach(btn => {
    btn.addEventListener('click', () => {
      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !isExpanded);
    });
  });

  // Pricing Toggle (Monthly / Annual)
  const toggleBtns = document.querySelectorAll('.pricing-toggle .toggle-btn');
  const priceDisplays = document.querySelectorAll('[data-monthly][data-annual]');

  toggleBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Update active state
      toggleBtns.forEach(b => b.classList.remove('active'));
      e.target.classList.add('active');

      const isAnnual = e.target.textContent.toLowerCase().includes('annual');

      // Update prices
      priceDisplays.forEach(display => {
        const value = isAnnual ? display.getAttribute('data-annual') : display.getAttribute('data-monthly');
        display.innerHTML = value === 'Contact Sales' ? value : `${value}<span>/user/mo</span>`;
      });
    });
  });

  // Team Size Slider
  const slider = document.getElementById('teamSizeSlider');
  const sliderValue = document.getElementById('teamSizeValue');
  if (slider && sliderValue) {
    slider.addEventListener('input', (e) => {
      sliderValue.textContent = e.target.value;
      // Could add logic here to highlight a specific plan based on size
    });
  }

  // Cookie Banner
  const cookieBanner = document.getElementById('cookieBanner');
  const acceptCookies = document.getElementById('acceptCookies');
  const rejectCookies = document.getElementById('rejectCookies');
  const manageCookies = document.getElementById('manageCookies');
  const cookieModal = document.getElementById('cookieModal');
  const closeCookieModal = document.getElementById('closeCookieModal');

  if (cookieBanner) {
    // Check if already dismissed
    if (!localStorage.getItem('cookieConsent')) {
      cookieBanner.style.display = 'flex';
    } else {
      cookieBanner.style.display = 'none';
    }

    const dismissBanner = () => {
      cookieBanner.style.display = 'none';
      localStorage.setItem('cookieConsent', 'true');
    };

    if (acceptCookies) acceptCookies.addEventListener('click', dismissBanner);
    if (rejectCookies) rejectCookies.addEventListener('click', dismissBanner);

    if (manageCookies && cookieModal) {
      manageCookies.addEventListener('click', () => {
        cookieModal.classList.add('active');
      });
    }

    if (closeCookieModal) {
      closeCookieModal.addEventListener('click', () => {
        cookieModal.classList.remove('active');
        dismissBanner();
      });
    }
  }

  // Auth Forms handling
  const authForms = document.querySelectorAll('form');
  authForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      // Simple mock redirection for demo purposes
      const emailInput = form.querySelector('input[type="email"]');
      if (emailInput && emailInput.value) {
        alert(`Proceeding with ${emailInput.value}...`);
      }
    });
  });
});

